"""Repo hygiene: stdlib-only imports, compiles cleanly, stdout discipline."""
from __future__ import annotations

import ast
import subprocess
import sys
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parent.parent
PACKAGE = REPO_ROOT / "linkvault"
SOURCES = sorted(PACKAGE.glob("*.py"))

# Fallback for interpreters without sys.stdlib_module_names (3.9): modules linkvault may use.
STDLIB_FALLBACK = {
    "__future__", "argparse", "calendar", "datetime", "hashlib", "hmac", "http", "json", "os",
    "re", "secrets", "signal", "socketserver", "sqlite3", "sys", "threading", "time",
    "traceback", "types", "urllib",
}
STDLIB = set(getattr(sys, "stdlib_module_names", ())) or STDLIB_FALLBACK


def _tree(path):
    return ast.parse(path.read_text(encoding="utf-8"), filename=str(path))


def _imported_roots(tree):
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                yield alias.name.split(".")[0]
        elif isinstance(node, ast.ImportFrom) and node.level == 0:
            yield (node.module or "").split(".")[0]


def test_sources_found():
    assert {p.name for p in SOURCES} >= {"__init__.py", "__main__.py", "server.py", "client.py"}


@pytest.mark.parametrize("path", SOURCES, ids=lambda p: p.name)
def test_imports_are_stdlib_or_linkvault(path):
    third_party = {r for r in _imported_roots(_tree(path)) if r not in STDLIB and r != "linkvault"}
    assert not third_party, "%s imports non-stdlib modules: %s" % (path.name, sorted(third_party))


def test_compileall(tmp_path):
    proc = subprocess.run(
        [sys.executable, "-m", "compileall", "-q", str(PACKAGE)],
        capture_output=True, text=True, cwd=str(REPO_ROOT),
        env={"PYTHONPYCACHEPREFIX": str(tmp_path / "pyc")})
    assert proc.returncode == 0, proc.stdout + proc.stderr


def _is_stdout_print(call):
    if not (isinstance(call.func, ast.Name) and call.func.id == "print"):
        return False
    return not any(kw.arg == "file" for kw in call.keywords)


def _stdout_writes(path):
    """Yield (function name, call node) for print() to stdout and sys.stdout uses."""
    tree = _tree(path)
    for func in [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)]:
        for node in ast.walk(func):
            if isinstance(node, ast.Call) and _is_stdout_print(node):
                yield func.name, node
            elif (isinstance(node, ast.Attribute) and node.attr == "stdout"
                  and isinstance(node.value, ast.Name) and node.value.id == "sys"):
                yield func.name, node


def _is_ready_line(call):
    flushed = any(kw.arg == "flush" and isinstance(kw.value, ast.Constant) and kw.value.value is True
                  for kw in call.keywords)
    first = call.args[0] if call.args else None
    text = first.left if isinstance(first, ast.BinOp) else first
    return flushed and isinstance(text, ast.Constant) and str(text.value).startswith("LISTENING ")


@pytest.mark.parametrize("path", SOURCES, ids=lambda p: p.name)
def test_no_stray_stdout(path):
    if path.name == "client.py":  # the client's output is its job
        return
    stray = []
    for func, node in _stdout_writes(path):
        allowed = (path.name == "server.py" and func == "serve"
                   and isinstance(node, ast.Call) and _is_ready_line(node))
        if not allowed:
            stray.append("%s:%d in %s()" % (path.name, node.lineno, func))
    assert not stray, "stdout writes outside the ready line: %s" % stray


def test_exactly_one_ready_line_print():
    ready = [n for f, n in _stdout_writes(PACKAGE / "server.py") if f == "serve"]
    assert len(ready) == 1 and _is_ready_line(ready[0])
